class Solution {
  public double[] sampleStats(int[] count) {
    long total = 0, sum = 0;
    int minimum = -1, maximum = 0, mode = 0, modeCount = 0;
    for (int value = 0; value < count.length; value++) {
      int frequency = count[value];
      if (frequency == 0) continue;
      if (minimum == -1) minimum = value;
      maximum = value;
      total += frequency;
      sum += (long) value * frequency;
      if (frequency > modeCount) {
        modeCount = frequency;
        mode = value;
      }
    }
    long middleLeft = (total + 1) / 2, middleRight = (total + 2) / 2;
    long seen = 0;
    int left = minimum, right = minimum;
    for (int value = minimum; value <= maximum; value++) {
      seen += count[value];
      if (seen >= middleLeft) {
        left = value;
        break;
      }
    }
    seen = 0;
    for (int value = minimum; value <= maximum; value++) {
      seen += count[value];
      if (seen >= middleRight) {
        right = value;
        break;
      }
    }
    return new double[] {minimum, maximum, (double) sum / total, (left + right) / 2.0, mode};
  }
}
